package org.marketreview.nativeapp;
import android.database.Cursor;
import android.database.sqlite.SQLiteDatabase;
import java.io.File;
import org.json.*;
final class SectorResearchStore {
 final File file;
 SectorResearchStore(File f)throws Exception{file=f;File parent=f.getAbsoluteFile().getParentFile();SectorResearchModel.require(parent.isDirectory()||parent.mkdirs(),"库目录无效");SQLiteDatabase db=open();try{int id=0;try(Cursor c=db.rawQuery("PRAGMA application_id",null)){c.moveToFirst();id=c.getInt(0);}if(id==0){try(Cursor c=db.rawQuery("SELECT count(*) FROM sqlite_master WHERE type='table' AND name NOT LIKE 'sqlite_%' AND name!='android_metadata'",null)){c.moveToFirst();SectorResearchModel.require(c.getInt(0)==0,"目标非空；拒绝重建");}db.beginTransaction();try{db.execSQL("CREATE TABLE records(kind TEXT NOT NULL,id TEXT NOT NULL,payload BLOB NOT NULL,PRIMARY KEY(kind,id))");db.execSQL("PRAGMA application_id=1397903921");db.setTransactionSuccessful();}finally{db.endTransaction();}}else SectorResearchModel.require(id==1397903921,"库身份不符");try(Cursor c=db.rawQuery("SELECT kind,id,payload FROM records LIMIT 0",null)){} }finally{db.close();}}
 SQLiteDatabase open(){return SQLiteDatabase.openOrCreateDatabase(file,null);}
 static JSONObject load(SQLiteDatabase db,String kind,String id)throws Exception{long length;try(Cursor c=db.rawQuery("SELECT length(CAST(payload AS BLOB)) FROM records WHERE kind=? AND id=?",new String[]{kind,id})){if(!c.moveToNext())return new JSONObject();length=c.getLong(0);}SectorResearchModel.require(length>0&&length<=25*1024*1024,"记录长度无效或超过25MiB");java.io.ByteArrayOutputStream bytes=new java.io.ByteArrayOutputStream((int)length);for(int offset=0;offset<length;){int count=(int)Math.min(65536,length-offset);try(Cursor c=db.rawQuery("SELECT substr(CAST(payload AS BLOB),?,?) FROM records WHERE kind=? AND id=?",new String[]{String.valueOf(offset+1),String.valueOf(count),kind,id})){SectorResearchModel.require(c.moveToNext(),"读取时记录已变化");byte[] part=c.getBlob(0);SectorResearchModel.require(part!=null&&part.length==count,"原文分块不完整");bytes.write(part);offset+=count;}}String text=java.nio.charset.StandardCharsets.UTF_8.newDecoder().onMalformedInput(java.nio.charset.CodingErrorAction.REPORT).onUnmappableCharacter(java.nio.charset.CodingErrorAction.REPORT).decode(java.nio.ByteBuffer.wrap(bytes.toByteArray())).toString();new EvidenceReviewModel.Syntax(text).check();return new JSONObject(text);}
 JSONArray list(String kind)throws Exception{SQLiteDatabase db=open();try{java.util.ArrayList<String> ids=new java.util.ArrayList<>();try(Cursor c=db.rawQuery("SELECT id FROM records WHERE kind=? ORDER BY rowid DESC",new String[]{kind})){while(c.moveToNext())ids.add(c.getString(0));}JSONArray a=new JSONArray();for(String id:ids)a.put(SectorResearchModel.validate(load(db,kind,id)));return a;}finally{db.close();}} JSONObject preview(String text)throws Exception{JSONArray a=SectorResearchModel.decode(text);return new JSONObject().put("records",a).put("digest",SectorResearchModel.fingerprint(a)).put("mergePolicy","keep-existing");}
 void merge(JSONObject p)throws Exception{SectorResearchModel.require(p.optString("mergePolicy").equals("keep-existing")&&p.optString("digest").equals(SectorResearchModel.fingerprint(p.getJSONArray("records"))),"预览内容已变更");JSONArray a=p.getJSONArray("records");for(int i=0;i<a.length();i++)SectorResearchModel.validate(a.getJSONObject(i));SQLiteDatabase db=open();try{db.beginTransaction();try{for(int i=0;i<a.length();i++){JSONObject r=a.getJSONObject(i);JSONObject existing=load(db,r.getString("kind"),r.getString("id"));boolean found=existing.length()>0;if(found)SectorResearchModel.require(SectorResearchModel.canonicalEqual(existing,r),"同身份内容冲突；未覆盖历史");if(!found)db.execSQL("INSERT INTO records(kind,id,payload) VALUES(?,?,?)",new Object[]{r.getString("kind"),r.getString("id"),SectorResearchModel.json(r)});}db.setTransactionSuccessful();}finally{db.endTransaction();}}finally{db.close();}}
 void put(JSONObject r)throws Exception{JSONArray a=new JSONArray().put(r);merge(new JSONObject().put("records",a).put("digest",SectorResearchModel.fingerprint(a)).put("mergePolicy","keep-existing"));}
 String backup()throws Exception{JSONArray a=new JSONArray();for(String k:new String[]{"packets","results","artifacts","associations","reviews"}){JSONArray rows=list(k);for(int i=0;i<rows.length();i++)a.put(rows.get(i));}long total=SectorResearchModel.json(a).getBytes(java.nio.charset.StandardCharsets.UTF_8).length;for(String id:aiReportIds()){JSONObject r=aiReport(id);total+=SectorResearchModel.json(r).getBytes(java.nio.charset.StandardCharsets.UTF_8).length+1;SectorAiModel.need(total<=25*1024*1024,"完整备份超过25MiB，原件保留");a.put(r);}SectorRelationStore reviews=new SectorRelationStore(file,file);for(String id:reviews.versions("")){JSONObject r=reviews.readVersion(id);total+=SectorResearchModel.json(r).getBytes(java.nio.charset.StandardCharsets.UTF_8).length+1;SectorAiModel.need(total<=25*1024*1024,"完整备份超过25MiB，原件保留");a.put(r);}String text=SectorResearchModel.json(new JSONObject().put("schema","sector-research-v1").put("records",a));SectorResearchModel.require(text.getBytes(java.nio.charset.StandardCharsets.UTF_8).length<=25*1024*1024,"备份超过25MiB");return text;}
 JSONObject state()throws Exception{SQLiteDatabase db=open();try{db.beginTransaction();try{JSONObject r=load(db,"private","state");db.setTransactionSuccessful();return r;}finally{db.endTransaction();}}finally{db.close();}}
 String saveState(JSONObject s,String expected)throws Exception{SectorResearchModel.require(SectorResearchModel.json(s).getBytes(java.nio.charset.StandardCharsets.UTF_8).length<=25*1024*1024,"草稿过大");SQLiteDatabase db=open();try{db.beginTransaction();try{JSONObject old=load(db,"private","state");SectorResearchModel.require(old.optString("revision").equals(expected),"另一入口已更新草稿；请重开页面后再编辑");String revision=java.util.UUID.randomUUID().toString();JSONObject r=new JSONObject(SectorResearchModel.json(s)).put("revision",revision);db.execSQL("INSERT OR REPLACE INTO records(kind,id,payload)VALUES('private','state',?)",new Object[]{SectorResearchModel.json(r)});db.setTransactionSuccessful();return revision;}finally{db.endTransaction();}}finally{db.close();}}
 void saveAiReport(JSONObject source,File businessFile,SectorAiModel.Scopes scopes,java.util.function.BooleanSupplier cancelled)throws Exception{
  SectorAiModel.need(cancelled!=null&&!cancelled.getAsBoolean(),"研究保存已取消");JSONObject record=SectorAiModel.copy(source);SectorAiModel.validateRecord(record);JSONObject plan=record.getJSONObject("plan");SectorAiModel.need(businessFile.isFile(),"原业务库不存在，未创建");
  try(SQLiteDatabase db=open()){db.execSQL("ATTACH DATABASE ? AS evidence",new Object[]{businessFile.getAbsolutePath()});db.beginTransactionNonExclusive();try{
   SectorAiModel.need(!cancelled.getAsBoolean(),"研究保存已取消");int matched=0;JSONArray current=scopes==null?new JSONArray():scopes.current();for(int i=0;i<current.length();i++){JSONObject s=current.getJSONObject(i);if(SectorAiModel.scopeKey(s).equals(SectorAiModel.scopeKey(plan.getJSONObject("scope")))){matched++;SectorAiModel.need(SectorAiModel.equal(s,plan.getJSONObject("scope")),"主题版本已变化，候选保留，未保存");}}SectorAiModel.need(matched==1,"主题缺失或重复，未保存");
   JSONArray docs=plan.getJSONArray("materials");for(int i=0;i<docs.length();i++){SectorAiModel.need(!cancelled.getAsBoolean(),"研究保存已取消");JSONObject d=docs.getJSONObject(i);try(Cursor c=db.rawQuery("SELECT length(CAST(payload AS BLOB)),CASE WHEN length(CAST(payload AS BLOB))<=1048576 THEN CAST(payload AS BLOB) ELSE NULL END FROM evidence.records WHERE kind=? AND id=?",new String[]{d.getString("kind"),d.getString("id")})){SectorAiModel.need(c.moveToFirst()&&c.getLong(0)>0&&c.getLong(0)<=1048576&&!c.isNull(1),"完整来源缺失或变大，未保存");SectorAiModel.need(SectorAiModel.equal(CreatorAiModel.parseObject(c.getBlob(1)),d.getJSONObject("row")),"完整来源版本已变化，未保存");}}
   try(Cursor c=db.rawQuery("SELECT count(*) FROM records WHERE kind='ai-reports'",null)){c.moveToFirst();SectorAiModel.need(c.getInt(0)<1000,"报告历史已满1000条，原件保留");}SectorAiModel.need(!cancelled.getAsBoolean(),"研究保存已取消");
   db.execSQL("INSERT INTO records(kind,id,payload) VALUES('ai-reports',?,?)",new Object[]{record.getString("id"),record.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8)});SectorAiModel.need(!cancelled.getAsBoolean(),"研究保存已取消");db.setTransactionSuccessful();
  }finally{db.endTransaction();}}
 }

 java.util.ArrayList<String> aiReportIds()throws Exception{return SectorReportReader.ids(file);}
 JSONObject aiReport(String id)throws Exception{return SectorReportReader.read(file,id);}
}


